=python3 - <<'PY'
import json
import subprocess
import urllib.parse

encoded = '''{{ encodeURIComponent($json.hermesCommand) }}'''
msg = urllib.parse.unquote(encoded)

try:
    proc = subprocess.run(
        ["hermes-command", "telegram", "--message", msg],
        cwd="/root/.hermes",
        capture_output=True,
        text=True,
        timeout=180,
    )
    stdout = (proc.stdout or "").strip()
    stderr = (proc.stderr or "").strip()
    try:
        payload = json.loads(stdout) if stdout else {}
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {"raw_stdout": stdout}
    payload.setdefault("ok", proc.returncode == 0)
    if not payload.get("telegram_reply"):
        payload["telegram_reply"] = stdout or stderr or f"Done. Code: {proc.returncode}"
    payload["exit_code"] = proc.returncode
except Exception as exc:
    payload = {"ok": False, "telegram_reply": "Error: " + str(exc)}

print(json.dumps(payload, ensure_ascii=False))
PY
